import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"连接 SQL Server","description":"使用实际主机和端口配置 SQL Server 业务库，测试账号与 TLS，再进入查询工作台。","frontmatter":{"title":"连接 SQL Server","description":"使用实际主机和端口配置 SQL Server 业务库，测试账号与 TLS，再进入查询工作台。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/sqlserver.md","filePath":"zh/使用指南/连接SQLServer.md"}'),s={name:"zh/guide/sqlserver.md"};function o(n,t,i,h,l,S){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="连接-sql-server" tabindex="-1">连接 SQL Server <a class="header-anchor" href="#连接-sql-server" aria-label="Permalink to &quot;连接 SQL Server&quot;">​</a></h1><p>本页连接外部 SQL Server。先向数据库负责人取得可从平台访问的主机、实际端口、数据库名、专用账号与 TLS 要求。</p><p>命名实例、动态端口或网络转发的情况，应先确认最终可连接的地址和端口，不能只输入一个实例名称猜测连接方式。</p><h2 id="_1-填写连接" tabindex="-1">1. 填写连接 <a class="header-anchor" href="#_1-填写连接" aria-label="Permalink to &quot;1. 填写连接&quot;">​</a></h2><p>进入 <strong>“数据中心” → “接入源” → “新建连接”</strong>，选择 <strong>“SQL Server”</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>怎样填写</th></tr></thead><tbody><tr><td>连接名称</td><td>团队能够辨认的业务连接名称</td></tr><tr><td>主机地址、端口</td><td>使用实际地址，默认端口 1433 仅在服务确实使用时保留</td></tr><tr><td>数据库名</td><td>已存在且账号获准使用的数据库</td></tr><tr><td>用户名、密码</td><td>按表单配置数据库凭据，不因默认提示 sa 就共用最高权限账号</td></tr><tr><td>SSL/TLS 配置</td><td>与服务端加密及证书要求一致</td></tr><tr><td>连接超时</td><td>在其他参数中按网络和服务安排设置，不以不断增大超时绕过连接故障</td></tr></tbody></table><h2 id="_2-测试与保存" tabindex="-1">2. 测试与保存 <a class="header-anchor" href="#_2-测试与保存" aria-label="Permalink to &quot;2. 测试与保存&quot;">​</a></h2><p>点击 **“测试连接”**并检查结果，再点击 <strong>“创建连接”</strong>。保存后从列表重新打开，核对类型、名称和测试状态。</p><p>认证失败时请数据库负责人核对账号与数据库授权；TLS 失败先核对证书，不把服务器管理账号或真实口令发送给 AI 排查。</p><h2 id="_3-查询与输出" tabindex="-1">3. 查询与输出 <a class="header-anchor" href="#_3-查询与输出" aria-label="Permalink to &quot;3. 查询与输出&quot;">​</a></h2><p>打开连接工作台，选择表或已有查询；需要新查询时使用 <strong>“新建查询”</strong>，按 SQL Server 语法填写。</p><p>运行前确认不是未经授权的写入操作。需要生成工程可用的数据点时，核对查询输出配置，使用 <strong>“保存并生成数据点”</strong>，再到<a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a>确认来源和类型；普通保存不等于生成点，详见<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 数据点指南</a>。</p><p>通用维护、保存与测试的区别，以及删除依赖见<a href="/induframe-docs/zh/guide/access-sources.html">管理接入源</a>。</p>',13)])])}const c=e(s,[["render",o]]);export{_ as __pageData,c as default};
